-- WA alpine audit batch 132 (pass 3) — 2026-08-20
-- Routes checked: wa_hadley_peak_cougar_divide, wa_hadley_peak_skyline_divide,
--   wa_helmet_butte_standard_route, wa_himmelhorn_southeast_route, wa_honeymoon_route,
--   wa_hourglass_gully_winter, wa_hozomeen_mountain_north_peak_north_route,
--   wa_hozomeen_mountain_southeast_face
--
-- Run with: npm run check:sql -- audits/sql/2026-08-20-batch-132.sql   (already run; see log)
--
-- The two statements below (waypoints, high_point_ft/face) are small and safe to paste
-- directly into the SQL Editor. The two bivy statements further down are each ~4.6KB —
-- well past the ~4000-byte soft limit CLAUDE.md documents for the SQL Editor silently
-- truncating a paste. Apply those two via a small Node script with the service key
-- (patchRow from scripts/lib/supabase-env.mjs) rather than pasting, or split each one at
-- the $json$ boundary and verify the row afterward if pasting by hand.

-- wa_hadley_peak_cougar_divide: waypoints[1] (the route's own Summit-type waypoint, "Hadley
-- Peak") stores elev/elevFt 7470, which is 45 ft below the sibling route
-- wa_hadley_peak_skyline_divide's summit waypoint for the SAME peak (7515 ft) and below two
-- independent external sources: listsofjohn.com lists Hadley Peak at 7,515 ft, and PeakVisor
-- (citing USGS-derived data) lists 7,513 ft. Corrected to 7515 to agree with the sibling
-- route and the stronger/more precise of the two external figures.
UPDATE routes SET waypoints = jsonb_set(
  jsonb_set(waypoints, '{1,elev}', '7515'),
  '{1,elevFt}', '7515'
)
WHERE id = 'wa_hadley_peak_cougar_divide';

-- wa_hozomeen_mountain_southeast_face: high_point_ft stored 8071, which is Hozomeen
-- Mountain's NORTH Peak elevation (confirmed via SummitPost/Peakbagger-derived sources:
-- North Peak 8,071 ft, South Peak 8,003 ft). This route's own Summit waypoint is "Hozomeen
-- Mountain, South Peak" at elev 8003, and its name ("Southeast Face (Standard)") plus its
-- own Hazard waypoint ("Southeast buttress — loose rock / crux chimney") both describe the
-- line to the South Peak, not the North Peak. The sibling route
-- wa_hozomeen_mountain_north_peak_north_route already correctly carries high_point_ft 8071
-- for the North Peak. Corrected this route's high_point_ft to match its own recorded summit
-- (8003), and its face field — which read "North Peak (main/highest summit)", a fact about
-- the mountain rather than a description of this route's own face — to match this route's own
-- aspect field (E-SE) and its own hazard waypoint's wording.
UPDATE routes SET high_point_ft = 8003,
  face = 'Southeast Buttress (South Peak)'
WHERE id = 'wa_hozomeen_mountain_southeast_face';

-- --- large statements below (~4.6KB each) — see note above before pasting ---

-- wa_hadley_peak_cougar_divide: bivy[] contained 6 entries but only 3 belong to this route/
-- peak. The other 3 ("Crag View, Squak Glacier", "Upper Squak benches...", "Coleman Glacier
-- bivy under the Black Buttes north faces") describe camps for Sherman Peak's Squak Glacier
-- route and Mount Baker's Coleman Glacier / Black Buttes ice routes — a different mountain
-- entirely, ~9 miles away, with no connection to Hadley Peak's Cougar Divide approach. The
-- notes text names those routes/peaks explicitly, so this is confirmed by the row's own
-- content, not an external source. Same defect class this repo's CLAUDE.md already tracks
-- (data written for one peak landing on another). The identical contaminated array is also
-- on wa_hadley_peak_skyline_divide (same area_id, fixed below).
UPDATE routes SET bivy = $json$[{"elev": 5100, "name": "Cougar Divide meadow camps", "type": "camp", "notes": "This is the north-side approach to Hadley Peak and it has nothing to do with the Black Buttes or the Coleman \u2014 a party here is on the far side of the mountain from the Heliotrope Ridge climbers. Cougar Divide is an unofficial, unmaintained path along the ridge crest, reached from Wells Creek Road, whose first several miles are badly potholed to the Nooksack bridge and then improve. From the meadows at the head of the divide the ground opens onto Chowder Ridge, and the connection east along the ridge leads to Hadley. The gate opening in July combined with mosquitoes that are genuinely bad here until midsummer pushes the sensible window to mid-August through early October, which is also when the talus is clear and the route is straightforward walking with the odd second-class step.", "water": "Better than anywhere else on this side. A creek fed by a lingering snowfield runs at the upper camp through most of the season, and there are ponds along the divide that are worth treating and not drinking untreated. Water gets scarce once the snowfield goes.", "permit": "Mt Baker-Snoqualmie National Forest, Mount Baker Wilderness. No overnight permit and no climbing permit. The access road is gated seasonally, closed from the start of November until the second week of July for wildlife, which is the single biggest planning constraint on this side of the mountain. Party size 12, no campfires, pack out all waste.", "capacity": "A handful of small sites in the meadows near the head of the divide; pick rocky ground rather than heather, which recovers slowly here"}, {"elev": 6000, "name": "Skyline Divide crest camps", "type": "camp", "notes": "The other approach to Hadley Peak, from the west along the divide and over Chowder Ridge. The road in has been the problem for years rather than the trail: flood damage at around mile three has left the trailhead inaccessible to vehicles for extended periods with no firm repair date, and the trail has been listed as closed on that account, so this is the first thing to confirm and not an afterthought. When it goes, the crest is easy walking with big views and the last three quarters of a mile up to Chowder Ridge is talus with one steeper step before you top out west of the Hadley Glacier. Camping on the open crest means taking whatever weather arrives off the mountain, and the exposure is the reason parties often drop into the basin instead.", "water": "None at the trailhead and none along the trail after early summer, when the snow patches below the crest are gone. Carry everything or plan the trip around a lingering snowfield you have confirmed is still there.", "permit": "Mt Baker-Snoqualmie National Forest, Mount Baker Wilderness. A recreation pass is required at the trailhead. No campfires anywhere, party size capped at 12, all waste packed out. There is no permit or quota for camping, but the meadows are heavily used and heavily damaged, so camp on bare ground.", "capacity": "Several exposed sites along the open crest of the divide once the trail tops out; popular and visible, with no screening from wind or weather"}, {"elev": 5300, "name": "Deadhorse Creek basin, below Chowder Ridge", "type": "camp", "notes": "The basin sits between Skyline Divide and Cougar Divide, just short of the climb onto Chowder Ridge, and it solves the problem both crest camps have: it has water and it has shelter. A party approaching Hadley from either road can drop into it, sleep out of the wind, and take the ridge in the morning with full bottles. Summit day from here is short by any standard on this mountain. It is subalpine meadow and creek terrain, so camp on durable ground well back from the water. Season is the same as everything else on the north side, mid-August into early October, held back at the front end by mosquitoes and by the road gate on the Cougar Divide side and at the back end by the first real snow.", "water": "The most reliable water on the Hadley approach \u2014 the creek runs from snowmelt above the basin and holds up later than anything on the ridge crests. Treat it. This is the reason to camp here rather than higher.", "permit": "Mount Baker Wilderness, no overnight permit required. Recreation pass at whichever trailhead you start from. Party size 12, campfires prohibited, human waste and everything else packed out \u2014 there are no toilets on either divide.", "capacity": "Scattered informal sites in the basin between the two divides; sheltered, low use, no facilities of any kind"}]$json$::jsonb
WHERE id = 'wa_hadley_peak_cougar_divide';

-- wa_hadley_peak_skyline_divide: identical bivy contamination as above (same 3 Mount
-- Baker/Sherman Peak entries prepended to the same 3 genuine Hadley Peak entries).
